import { FilterDropdown, normalizeFilter } from '../components/selects.js';
import{db,visible,modules}from'../store.js';import{esc,card,heading,tag,note,empty,field}from'../components/ui.js';
export function list(module,q='',filter='全部'){const f=normalizeFilter(filter);let ts=visible();if(module==='calls')ts=ts.filter(t=>!t.id.includes('FIN'));if(module==='approvals')ts=ts.filter(t=>t.submitted&&t.status==='待完工確認');if(module==='reports')ts=ts.filter(t=>t.submitted||t.report||db.drafts[t.id]);ts=ts.filter(t=>(f.category==='全部'||t.category===f.category)&&(f.status==='全部'||t.status===f.status)&&`${t.id} ${t.customer} ${t.contractNo} ${t.desc} ${t.serviceReportNo||''} ${t.cpNo||''} SR-${t.serviceReportNo||''} CP-${t.cpNo||''} ${t.report?.cpNo||''}`.toLowerCase().includes(q.toLowerCase()));return `${heading(modules[module][0])}${module==='approvals'?note('只確認本人負責的本次工作工單；不更改發票、收款或整體 M／M+P 狀態。'):''}${module==='reports'?`<button type="button" class="picker-trigger" data-report-picker aria-haspopup="listbox" aria-expanded="false"><span>${q?esc(q):'選擇工單編號'}</span><span aria-hidden="true">⌄</span></button>`:`<div class="search"><input id="search" aria-label="搜尋記錄" placeholder="搜尋客戶、合約或工單" value="${esc(q)}"></div>`}${FilterDropdown.fields(f)}<p class="muted">${ts.length} 項記錄 · ${module==='calls'?'CALL 受理與分流，不代表已成交':'本機演示狀態'}</p><div id="results">${ts.map(t=>card(t,module)).join('')||empty()}</div>`;}
export function quotes(id,q=''){if(id){let x=db.quotes.find(x=>x.id===id);if(!x)return empty('找不到報價');return `${heading('報價詳情')}${note('手機只讀。修訂、客戶接受及中單請使用 PC；即時後補記錄不重走接受／中單。')}<section class="panel"><h2>${esc(x.id)}</h2>${tag(x.status)}${field('客戶',x.customerName)}${field('版本',`R${x.revision||0}`)}${field('負責人',x.owner)}${field('類別',x.category||'原資料未標示，待核')}${field('總額 (HKD)',Number(x.totalAmount).toLocaleString('en-HK'))}</section>${heading('報價明細')}${(x.items||[]).map(i=>`<section class="panel"><h3>${esc(i.name)}</h3><p>${esc(i.spec)}</p>${field('數量',`${i.qty} ${i.unit}`)}${field('金額 (HKD)',Number(i.amount).toLocaleString('en-HK'))}</section>`).join('')}`;}let xs=db.quotes.filter(x=>`${x.id} ${x.customerName}`.toLowerCase().includes(q.toLowerCase()));return `${heading('報價查閱')}${note('CALL／SR 需報價進入公共待辦；正式接手、版本與成交操作保留 PC。')}<input id="search" aria-label="搜尋記錄" value="${esc(q)}" placeholder="搜尋報價或客戶">${db.quoteRequests.length?heading('公共報價待辦（演示）')+db.quoteRequests.map((r,i)=>`<a class="panel summary-link" href="#/quotes/request-${i}"><strong>${esc(r.ticketId)}</strong><p>${esc(r.text)}</p>${tag('待接手')}</a>`).join(''):''}${heading('報價記錄')}${xs.map(x=>`<a class="task-card" href="#/quotes/${encodeURIComponent(x.id)}"><div class="card-top"><span class="serial">${esc(x.id)} · R${x.revision||0}</span>${tag(x.status)}</div><h3>${esc(x.customerName)}</h3><p>${esc(x.title)}</p><strong>HK$ ${Number(x.totalAmount).toLocaleString('en-HK')}</strong></a>`).join('')||empty()}`;}
export function boundaries(m,id=''){
 if(m==='finance'){
  const records=db.tickets.filter(t=>t.status==='已完成');
  if(id){const t=records.find(t=>t.id===id);return t?`<section class="panel"><h3>${esc(t.customer)}</h3>${field('工作工單',t.id)}${field('本次工作',t.status)}${field('發票',t.invoiceStatus)}${field('收款',t.paymentStatus)}</section>`:empty('找不到財務記錄');}
  return `${heading('財務資料')}${note('業務完成、開票、收款各自獨立。本頁只查閱手機演示完成結果，不執行開票或收款。')}${records.map(t=>`<a class="panel summary-link" href="#/finance/${encodeURIComponent(t.id)}"><h3>${esc(t.customer)}</h3><p>${esc(t.id)}</p>${tag(t.status)}<small>查看財務狀態摘要 ⌄</small></a>`).join('')}`;
 }
 if(m==='materials'){
  const info=note('MR 申請完成、到貨、出庫均不自動等於可供施工。C-04：本次／本階段確認人與憑據待確認；可分階段供料。')+`<section class="panel"><h3>申請 → 採購 → 階段供料</h3><p>普通成交報價一張 MR；同一 MR 可關聯多張採購 PO。申請及領料操作保留 PC／倉庫通。</p><span class="tag amber">手機申請／出庫未開放</span></section>`;
  if(id==='scope')return info;
  const records=visible().filter(t=>t.report?.materialUse);
  if(id){const t=records.find(t=>t.id===id);return t?`<section class="panel"><h3>${esc(t.id)}</h3><p>${esc(t.report.materialUse)}</p><small>師傅現場使用備註，並非庫存扣賬</small></section>`:empty('找不到材料記錄');}
  return `${heading('材料與使用記錄')}<a class="panel summary-link" href="#/materials/scope"><h3>材料申請與領料範圍</h3><p>查看 MR／PO 與階段供料說明 ⌄</p><span class="tag amber">原交易未開放</span></a>${records.map(t=>`<a class="panel summary-link" href="#/materials/${encodeURIComponent(t.id)}"><h3>${esc(t.id)}</h3><p>${esc(t.report.materialUse)}</p><small>查看使用記錄 ⌄</small></a>`).join('')||empty('暫無手機現場使用記錄')}`;
 }
 const title=m==='tender'?'標書管理':'倉庫通邊界';
 const info=note(m==='tender'?'手機投標操作尚未確認，本期保留 PC 標書管理入口。':'PC EC 沒有獨立倉庫角色。倉庫在倉庫通辦理；不在手機原型新增出庫或施工放行權限。')+`<section class="panel"><h3>此操作保留原系統</h3><p>本頁只供評審範圍說明，未實作任何提交或審批交易。</p></section>`;
 return id?info:`${heading(title)}<a class="panel summary-link" href="#/${m}/scope"><h3>查看操作範圍</h3><p>原系統分工及手機未開放事項 ⌄</p></a>`;
}
